64	    /**
65	     * Syntactic email validation: a non-empty local part, a single '@', and a
66	     * domain with at least one dot-separated label ending in a letter-only TLD.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
