213	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
214	     * component contributes the empty string, and the email is lower-cased so the comparison is
215	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
216	     */
217	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
218	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
219	        String emailKey = email == null ? "" : email.toLowerCase();
220	        String household = householdId == null ? "" : householdId;
221	        return telephone + "|" + emailKey + "|" + household;
222	    }
223	
224	    /**
225	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
226	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
227	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
228	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
229	     * only on the owner's own region and identity, not on how many owners already exist.
230	     */
231	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
232	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
233	    }
234	
235	    /**
236	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
237	     */
238	    private static String hash8(String input) {
239	        try {
240	            byte[] digest = MessageDigest.getInstance("SHA-256")
241	                .digest(input.getBytes(StandardCharsets.UTF_8));
242	            StringBuilder sb = new StringBuilder(digest.length * 2);
243	            for (byte b : digest) {
244	                sb.append(String.format("%02x", b));
245	            }
246	            return sb.substring(0, 8).toUpperCase();
247	        }
248	        catch (java.security.NoSuchAlgorithmException e) {
249	            throw new IllegalStateException(e);
250	        }
251	    }
252	
253	    /**
254	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
255	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
256	     * fixed city-to-region table, else {@code "UNKNOWN"}.
257	     */
258	    private static String region(String postcode, String city) {
259	        String fromPostcode = regionForPostcode(postcode);
260	        return fromPostcode != null ? fromPostcode : regionForCity(city);
261	    }
262	
263	    /**
264	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
265	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
266	     */
267	    private static String regionForPostcode(String postcode) {
268	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
269	            return null;
270	        }
271	        int value = Integer.parseInt(postcode);
272	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
273	            int[] range = entry.getValue();
274	            if (value >= range[0] && value <= range[1]) {
275	                return entry.getKey();
276	            }
277	        }
278	        return null;
279	    }
280	
281	    /**
282	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
283	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
284	     */
285	    static LocalDate toBusinessDay(LocalDate date) {
286	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
287	            date = date.plusDays(1);
288	        }
289	        return date;
290	    }
291	
292	    /**
293	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
294	     * using the same per-day accumulation path as the daily create-limit rule.
295	     */
296	    private long ownersCreatedOn(LocalDate registrationDate) {
297	        LocalDate day = toBusinessDay(registrationDate);
298	        return this.clinicService.findAllOwners().stream()
299	            .map(Owner::getRegistrationDate)
300	            .filter(existing -> existing != null)
301	            .map(OwnerRestControllerV1::toBusinessDay)
302	            .filter(day::equals)
303	            .count();
304	    }
305	
306	    /**
307	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
308	     * postcode against the owner's city region.
309	     */
310	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
311	        "NSW", new int[] {2000, 2099},
312	        "VIC", new int[] {3000, 3099},
313	        "QLD", new int[] {4000, 4099});
314	
315	    /**
316	     * Resolve an owner's region from the city using the fixed city-to-region table
317	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
318	     * when the city is not listed.
319	     */
320	    private static String regionForCity(String city) {
321	        return switch (city == null ? "" : city) {
322	            case "Sydney" -> "NSW";
323	            case "Melbourne" -> "VIC";
324	            case "Brisbane" -> "QLD";
325	            default -> "UNKNOWN";
326	        };
327	    }
328	
329	    /**
330	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
331	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
332	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
333	     */
334	    private static boolean isPostcodeValid(String postcode, String city) {
335	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
336	            return false;
337	        }
338	        int[] range = REGION_POSTCODES.get(regionForCity(city));
339	        if (range == null) {
340	            return true;
341	        }
342	        int value = Integer.parseInt(postcode);
343	        return value >= range[0] && value <= range[1];
344	    }
345	
346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
349	        Collection<Owner> owners;
350	        if (lastName != null) {
351	            owners = this.clinicService.findOwnerByLastName(lastName);
352	        } else {
353	            owners = this.clinicService.findAllOwners();
354	        }
355	        if (owners.isEmpty()) {
356	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
357	        }
358	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
364	        Owner owner = this.clinicService.findOwnerById(ownerId);
365	        if (owner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
369	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
370	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
371	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
372	    }
373	
374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Override
376	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
377	        String telephone = toE164(ownerFieldsDto.getTelephone());
378	        if (telephone == null) {
379	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
380	        }
381	        String email = ownerFieldsDto.getEmail();
382	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
383	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
384	        }
385	        String address = normaliseAddress(ownerFieldsDto.getAddress());
386	        if (address.isEmpty()) {
387	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
388	        }
389	        String postcode = ownerFieldsDto.getPostcode();
390	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
391	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
392	        }
393	        if (ownerFieldsDto.getRegistrationDate() != null
394	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
395	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
396	        }
397	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
398	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
399	        LocalDate registrationDate = toBusinessDay(effectiveDate);
400	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
401	            .map(Owner::getRegistrationDate)
402	            .filter(existing -> existing != null)
403	            .map(OwnerRestControllerV1::toBusinessDay)
404	            .filter(registrationDate::equals)
405	            .count();
406	        if (ownersCreatedThatDay >= 100) {
407	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
408	        }
409	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
410	        long ownersInCity = this.clinicService.findAllOwners().stream()
411	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
412	            .count();
413	        if (ownersInCity >= 50) {
414	            return new ResponseEntity<>(HttpStatus.CONFLICT);
415	        }
416	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
417	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
418	        String addressKey = address;
419	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
420	            .filter(existing ->
421	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
422	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
423	            .toList();
424	        String householdId = (sharesHousehold && !householdMembers.isEmpty())
425	            ? householdId(lastNameKey, addressKey) : null;
426	        String identityKey = identityKey(telephone, email, householdId);
427	        boolean identityInUse = this.clinicService.findAllOwners().stream()
428	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
429	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
430	        if (identityInUse) {
431	            return new ResponseEntity<>(HttpStatus.CONFLICT);
432	        }
433	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
434	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
435	            .filter(existing ->
436	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
437	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
438	            .count();
439	        HttpHeaders headers = new HttpHeaders();
440	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
441	        owner.setNamesakeCount(namesakeCount);
442	        owner.setAddress(address);
443	        owner.setTelephone(telephone);
444	        owner.setEmail(email == null ? null : email.toLowerCase());
445	        owner.setRegistrationDate(registrationDate);
446	        owner.setCustomerCode(nextCustomerCode(
447	            region(postcode, owner.getCity()), telephone, owner.getLastName()));
448	        if (householdId != null) {
449	            owner.setHouseholdId(householdId);
450	            for (Owner member : householdMembers) {
451	                if (member.getHouseholdId() == null) {
452	                    member.setHouseholdId(householdId);
453	                    this.clinicService.saveOwner(member);
454	                }
455	            }
456	        }
457	        this.clinicService.saveOwner(owner);
458	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
459	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
460	            ownerMapper.formatMembershipLevel(owner));
461	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
462	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
463	        headers.setLocation(UriComponentsBuilder.newInstance()
464	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
465	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
466	    }
467	
468	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
469	    @Override
470	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
471	        String telephone = toE164(ownerFieldsDto.getTelephone());
472	        if (telephone == null) {
473	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
474	        }
475	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
476	        if (currentOwner == null) {
477	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
478	        }
479	        String email = ownerFieldsDto.getEmail();
480	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
481	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
482	        }
483	        currentOwner.setAddress(ownerFieldsDto.getAddress());
484	        currentOwner.setCity(ownerFieldsDto.getCity());
485	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
486	        currentOwner.setLastName(ownerFieldsDto.getLastName());
487	        currentOwner.setTelephone(telephone);
488	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
489	        this.clinicService.saveOwner(currentOwner);
490	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
491	    }
492	
493	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
494	    @Transactional
495	    @Override
496	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
497	        Owner owner = this.clinicService.findOwnerById(ownerId);
498	        if (owner == null) {
499	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
500	        }
501	        this.clinicService.deleteOwner(owner);
502	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
503	    }
504	
505	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
506	    @Override
507	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
508	        Owner owner = this.clinicService.findOwnerById(ownerId);
509	        if (owner == null) {
510	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
